// TH16 v1.00a approved aliases of identical TH18 type slots (2026-11-07).
// Only the type this card uses is copied from transcribe/th16/touhou-bullets.ecl.
// 源 st04.ecl.txt GirlA04_at:748 etSprite(0, 8, 2) -> TH16 type 8 = TH16_RICE, color 2.
const TH16_RICE: int = 480;

// TH16 v1.00a Stage 4 道中 GirlA04 三组波次
// 源: st04.ecl.txt MainSub02:1512-1543（入口），GirlA04:709-717 / GirlA04F:719-740 /
//     GirlA04_at:742-813（依赖）。源帧 s=0 对应卡帧 OPENING_BUFFER。

const TIME_LIMIT: int = 2400;
const OPENING_BUFFER: int = 120;

const BULLET_RAMP_FRAMES: int = 60;

// 源 GirlA04_at:788 etEx(type=0x200000 VELTIME, a=60, r=目标标量速, s=-999999 保留角):
// 方向不变，标量速度在 60 帧内线性改到 r。
xformdef RICE_RAMP(target: fx) {
    step_speed(target, BULLET_RAMP_FRAMES + 65536 * EASE_LINEAR);
}

// 源 GirlA04:709-717 + GirlA04_at:742-813。
async sub girl_atk() {
    // 源 GirlA04_at:745 wait(60)
    wait(60);
    // 源 GirlA04_at:746-788 的发射器配置；难度掩码取对应档。
    // etAim(0,3) 固定方向整周环；etAngle 第二参 0.0 -> 层角偏 0。
    var ways: int = 8;
    var layers: int = 2;
    var v0: fx = 3.8fx;
    var v1: fx = 2.2fx;
    var goal: fx = 0.9fx;
    var gap: int = 50;
    var rank: int = global(GVAR_RANK);
    if rank == RANK_EASY {
        ways = 3; layers = 1; v0 = 1.5fx; v1 = 1.5fx; goal = 0.8fx; gap = 150;
    } else if rank == RANK_NORMAL {
        ways = 8; layers = 1; v0 = 3.5fx; v1 = 3.5fx; goal = 0.8fx; gap = 50;
    } else if rank == RANK_HARD {
        ways = 8; layers = 2; v0 = 3.8fx; v1 = 2.2fx; goal = 0.9fx; gap = 50;
    } else {
        ways = 8; layers = 2; v0 = 3.8fx; v1 = 2.2fx; goal = 1fx; gap = 40;
    }
    // 源 diffI($A,30,30,30,30) + GirlA04_at_1048 的 if ($A--)
    for it in 0..30 {
        // 源 GirlA04_at:792 etAngle(0, pi/2 + RANDF2*0.17453292, 0.0)：
        // 每轮抽一次基角（RANDF2 为 -1..1）。
        var ra: int = rand(65536);
        var u: fx = (ra - 32768) as fx / 32768;
        var base: angle = (16384 + ((1820fx * u) as int)) as angle;
        // 源先跳到 if ($B--)，B=1 只执行一次 etOn；随后仍有 wait(3)。
        // 层在外、路在内（源 etOn 生成序）。
        for q in 0..layers {
            var v: fx = v0;
            if layers > 1 { v = v0 + (v1 - v0) * (q as fx) / ((layers - 1) as fx); }
            for i in 0..ways {
                var a: angle = ((base as int) + (i * 65536) / ways) as angle;
                // 源 GirlA04_at:778 ANIM a=1 的出生退位移 position -= 4*velocity。
                _ = fire(TH16_RICE, 2,
                         $self_x - 4fx * v * cos(a),
                         $self_y - 4fx * v * sin(a),
                         v, a, RICE_RAMP(goal), none);
            }
        }
        wait(3);
        // 源难度 wait：E150 / N50 / H50 / L40。
        wait(gap);
    }
}

// 源 GirlA04F:719-740 主任务；调用者 GirlA04:709-717。
async sub girl() {
    set_invuln(65535);
    // 源 GirlA04F:722-723 setHurtbox(24,24) / setHitbox(16,16)，普通圆形取第一值×0.5。
    set_hurtbox(12fx);
    set_hitbox(8fx);
    // 源 GirlA01_color:457 flagSet(3)（其中已核 0x2 = 禁体碰）在 +60 处 flagClear(3)。
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spawn girl_atk();
    // 源 GirlA04F:727 moveVel(pi/2, 0.5)
    move_vel(0, 90deg, 0.5fx, EASE_LINEAR);
    wait(60);
    set_enemy_flag(ENEMY_NO_BODY, 0);
    // 源 GirlA04F:729 再写同一角/速，无变化。
    move_vel(60, 90deg, 0.5fx, EASE_LINEAR);
    wait(190);
    // 源 GirlA04F:731 pi/2 + RANDF2*0.5235988，在 t=250 抽样、t=440 使用。
    var ra: int = rand(65536);
    var u: fx = (ra - 32768) as fx / 32768;
    var turn: angle = (16384 + ((5461fx * u) as int)) as angle;
    wait(190);
    // 源 GirlA04F:733 moveVelTime(60,0,角,-1.0)：-1.0 为速度哨兵，保持 0.5。
    move_angle(60, turn, EASE_LINEAR);
    loop { wait(1000); }
}

// 源 MainSub02:1518-1541：一组 10 只，每只后 wait(40) 或 wait(30)。
sub spawn_row(first_x: fx, step_x: fx, hp: int, gap: int) {
    for i in 0..10 {
        _ = spawn_enemy(first_x + (i as fx) * step_x, 128fx, hp, 0, 1000, 0, girl);
        wait(gap);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    spawn_row(180fx, -40fx, 400, 40);
    spawn_row(180fx, -40fx, 400, 40);
    spawn_row(-180fx, 40fx, 300, 30);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
